const num=(v,a,b,d)=>Number.isFinite(Number(v))?Math.max(a,Math.min(b,Number(v))):d;
const color=(v,d='#d8d6cc')=>/^#[a-f\d]{6}$/i.test(v)?v:d;
const cross=(a,b,c)=>(b.x-a.x)*(c.z-a.z)-(b.z-a.z)*(c.x-a.x);
export function validatePolygon(v){const errors=[];if(!Array.isArray(v)||v.length<3||v.length>24)return {valid:false,errors:['Нужно 3–24 вершины']};if(v.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.z)||Math.abs(p.x)>12000||Math.abs(p.z)>12000))errors.push('Координаты: от −12000 до 12000 мм');let area=0;for(let i=0;i<v.length;i++){const a=v[i],b=v[(i+1)%v.length];area+=a.x*b.z-b.x*a.z;if(Math.hypot(b.x-a.x,b.z-a.z)<100)errors.push('Стена короче 100 мм');for(let j=i+2;j<v.length;j++){if(i===0&&j===v.length-1)continue;const c=v[j],d=v[(j+1)%v.length];if(cross(a,b,c)*cross(a,b,d)<=0&&cross(c,d,a)*cross(c,d,b)<=0&&Math.max(Math.min(a.x,b.x),Math.min(c.x,d.x))<=Math.min(Math.max(a.x,b.x),Math.max(c.x,d.x))&&Math.max(Math.min(a.z,b.z),Math.min(c.z,d.z))<=Math.min(Math.max(a.z,b.z),Math.max(c.z,d.z)))errors.push('Стены пересекаются');}}if(Math.abs(area)<100000)errors.push('Площадь слишком мала');return {valid:!errors.length,errors:[...new Set(errors)]};}
export function pointInPolygon(p,v){let inside=false;for(let i=0,j=v.length-1;i<v.length;j=i++){const a=v[j],b=v[i];if(Math.abs(cross(a,b,p))<.01&&p.x>=Math.min(a.x,b.x)&&p.x<=Math.max(a.x,b.x)&&p.z>=Math.min(a.z,b.z)&&p.z<=Math.max(a.z,b.z))return true;if((a.z>p.z)!==(b.z>p.z)&&p.x<(b.x-a.x)*(p.z-a.z)/(b.z-a.z)+a.x)inside=!inside;}return inside;}
export function roomVertices(r){return r.vertices||[{x:-r.width/2,z:-r.depth/2},{x:r.width/2,z:-r.depth/2},{x:r.width/2,z:r.depth/2},{x:-r.width/2,z:r.depth/2}];}
export function clampOpening(o={},length,height){const type=['door','window','opening'].includes(o.type)?o.type:'opening',width=num(o.width,100,length,Math.min(800,length)),sill=type==='window'?num(o.sill,0,height-100,900):0;return {id:String(o.id||'opening').slice(0,60),wallIndex:Math.round(num(o.wallIndex,0,23,0)),type,width,height:num(o.height,100,height-sill,Math.min(2100,height-sill)),sill,offset:num(o.offset,0,length-width,0),open:num(o.open,0,100,0)};}
export function calibratePlan(a,b,distanceMm){const px=Math.hypot(a.x-b.x,a.y-b.y);if(px<1||!Number.isFinite(distanceMm)||distanceMm<=0||distanceMm>30000)throw Error('Выберите две разные точки и положительное расстояние до 30000 мм');return {mmPerPixel:distanceMm/px,a,b,distanceMm};}
export function normalizeRoomExtensions(raw){const vertices=validatePolygon(raw.vertices).valid?raw.vertices.map(p=>({x:p.x,z:p.z})):null;const r={width:raw.width||5000,depth:raw.depth||4000,height:raw.height||2800,vertices};const v=roomVertices(r);const wallFinishes=(Array.isArray(raw.wallFinishes)?raw.wallFinishes:[]).slice(0,24).map(o=>({wallIndex:Math.round(num(o.wallIndex,0,v.length-1,0)),material:['paint','plaster','oak','marble','concrete'].includes(o.material)?o.material:'paint',color:color(o.color),roughness:num(o.roughness,.05,1,.5),scale:num(o.scale,.1,5,1)}));const openings=(Array.isArray(raw.openings)?raw.openings:[]).slice(0,40).filter(o=>o&&Number.isInteger(o.wallIndex)&&o.wallIndex>=0&&o.wallIndex<v.length).map((o,i)=>{const a=v[o.wallIndex],b=v[(o.wallIndex+1)%v.length];return clampOpening({...o,id:o.id||'opening-'+i},Math.hypot(b.x-a.x,b.z-a.z),r.height);});const obstacles=(Array.isArray(raw.obstacles)?raw.obstacles:[]).slice(0,30).filter(Boolean).map((o,i)=>({id:String(o.id||'obstacle-'+i).slice(0,60),type:o.type==='column'?'column':'obstacle',x:num(o.x,-12000,12000,0),z:num(o.z,-12000,12000,0),width:num(o.width,50,6000,400),depth:num(o.depth,50,6000,400),height:num(o.height,50,4500,r.height),rotation:num(o.rotation,-360,360,0),color:color(o.color)}));const services=(Array.isArray(raw.services)?raw.services:[]).slice(0,60).filter(Boolean).map((o,i)=>({id:String(o.id||'service-'+i).slice(0,60),type:['socket','pipe','vent','connection'].includes(o.type)?o.type:'connection',label:String(o.label||'Подключение').slice(0,60),x:num(o.x,-12000,12000,0),y:num(o.y,0,4500,900),z:num(o.z,-12000,12000,0),width:num(o.width,20,2000,80),height:num(o.height,20,3000,80),depth:num(o.depth,10,1000,40)}));let planImage=null;const p=raw.planImage;if(p&&typeof p.src==='string'&&p.src.length<1800000&&/^data:image\/(png|jpeg|webp);base64,[a-z\d+/=]+$/i.test(p.src)){planImage={src:p.src,visible:p.visible!==false,opacity:num(p.opacity,.05,.9,.45),mmPerPixel:num(p.mmPerPixel,.1,100,5),offsetX:num(p.offsetX,-12000,12000,0),offsetZ:num(p.offsetZ,-12000,12000,0),rotation:num(p.rotation,-360,360,0)};}return {vertices,wallFinishes,openings,obstacles,services,planImage};}
export function effectiveOpenings(r){const a=[...(r.openings||[])];if(!r.vertices){if(r.window)a.push(clampOpening({id:'legacy-window',wallIndex:0,type:'window',width:r.windowWidth,height:r.windowHeight,sill:r.windowSill,offset:r.width/2+r.windowX-r.windowWidth/2,open:r.windowOpen},r.width,r.height));if(r.door)a.push(clampOpening({id:'legacy-door',wallIndex:3,type:'door',width:r.doorWidth,height:r.doorHeight,offset:r.depth/2-r.doorZ-r.doorWidth/2,open:r.doorOpen},r.depth,r.height));}return a;}
export function moduleCorners(m){const a=(m.rotation||0)*Math.PI/180;return [[-1,-1],[1,-1],[1,1],[-1,1]].map(([x,z])=>({x:m.x+x*m.width/2*Math.cos(a)+z*m.depth/2*Math.sin(a),z:m.z-x*m.width/2*Math.sin(a)+z*m.depth/2*Math.cos(a)}));}
export function roomDiagnostics(r,modules=[]){const out=[],v=roomVertices(r),ops=effectiveOpenings(r);for(const m of modules.filter(m=>m.visible!==false)){if(!polygonInside(moduleCorners(m),v))out.push({code:'outside',moduleId:m.id,message:m.name+': за контуром комнаты'});for(const o of r.obstacles||[]){if(m.y<o.height&&rectanglesOverlap(m,o))out.push({code:'obstacle',moduleId:m.id,message:m.name+': возможное пересечение с выступом'});}}for(let i=0;i<ops.length;i++)for(let j=i+1;j<ops.length;j++){const a=ops[i],b=ops[j];if(a.wallIndex===b.wallIndex&&a.offset<b.offset+b.width&&b.offset<a.offset+a.width&&a.sill<b.sill+b.height&&b.sill<a.sill+a.height)out.push({code:'openings-overlap',message:'Проёмы стены '+(a.wallIndex+1)+' пересекаются'});}return out;}

export function polygonInside(poly,room){if(poly.some(p=>!pointInPolygon(p,room)))return false;for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],rx=b.x-a.x,rz=b.z-a.z,ts=[0,1];for(let j=0;j<room.length;j++){const c=room[j],d=room[(j+1)%room.length],sx=d.x-c.x,sz=d.z-c.z,den=rx*sz-rz*sx;if(Math.abs(den)<1e-8)continue;const t=((c.x-a.x)*sz-(c.z-a.z)*sx)/den,u=((c.x-a.x)*rz-(c.z-a.z)*rx)/den;if(t>0&&t<1&&u>=0&&u<=1)ts.push(t);}ts.sort((a,b)=>a-b);for(let j=1;j<ts.length;j++){const t=(ts[j-1]+ts[j])/2;if(!pointInPolygon({x:a.x+rx*t,z:a.z+rz*t},room))return false;}}return true;}
export function rectanglesOverlap(a,b){const pa=moduleCorners(a),pb=moduleCorners(b);for(const poly of [pa,pb])for(let i=0;i<2;i++){const q=poly[i],r=poly[i+1],nx=-(r.z-q.z),nz=r.x-q.x,aa=pa.map(p=>p.x*nx+p.z*nz),bb=pb.map(p=>p.x*nx+p.z*nz);if(Math.max(...aa)<=Math.min(...bb)||Math.max(...bb)<=Math.min(...aa))return false;}return true;}
